            V vertex = new V("V" + i);
            vertexMap.put("V" + i, vertex);
            target.addVertex(vertex);
        }

        // Generate edges
        for (int i = 0; i < target.getNumVertices(); i++) {
            for (int j = i + 1; j < target.getNumVertices(); j++) {
                E edge = new E("E" + i + j);
                edgeMap.put("E" + i + j, edge);
                target.addEdge(edge);
            }
        }

        // Store the results in the resultMap
        resultMap.putAll(vertexMap);
        resultMap.putAll(edgeMap);
    }
}

