public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    Pattern pattern = Pattern.compile("\\\\(.)");
    Matcher matcher = pattern.matcher(str);
    while (matcher.find()) {
        char c = matcher.group(1);
        if (c == '\\') {
            sb.append('\\');
        } else if (c == 'n') {
            sb.append('\n');
        } else if (c == 't') {
            sb.append('\t');
        } else if (c == 'r') {
            sb.append('\r');
        } else if (c == 'b') {
            sb.append('\b');
        } else if (c == 'f') {
            sb.append('\f');
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

