        System.arraycopy(nullBytes, 0, this.data, this.size, byteLength);
        this.size += byteLength;
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.data, this.size, byteLength);
        this.size += byteLength;
    }
    return this;
}

